const resolve = require('resolve');

class ResolverFactory {
  constructor(options = {}) {
    this.options = options;
  }

  cloneWithOptions(newOptions) {
    return new ResolverFactory({
      ...this.options,
      ...newOptions
    });
  }

  clearCache() {
  }

  sync(basedir, targetPath) {
    try {
      const extensions = this.options.extensions || ['.js', '.json', '.ts', '.tsx', '.mjs', '.cjs'];
      const moduleDirectory = this.options.modules || ['node_modules'];
      
      const resolvedPath = resolve.sync(targetPath, {
        basedir,
        extensions,
        moduleDirectory,
      });
      return { path: resolvedPath };
    } catch (err) {
      return { error: err.message };
    }
  }

  async async(basedir, targetPath) {
    return new Promise((resolvePromise) => {
      const extensions = this.options.extensions || ['.js', '.json', '.ts', '.tsx', '.mjs', '.cjs'];
      const moduleDirectory = this.options.modules || ['node_modules'];
      
      resolve(targetPath, {
        basedir,
        extensions,
        moduleDirectory,
      }, (err, res) => {
        if (err) {
          resolvePromise({ error: err.message });
        } else {
          resolvePromise({ path: res });
        }
      });
    });
  }
}

module.exports = {
  ResolverFactory,
};
